package space

import (
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// vectors mirrors testdata/vectors.json, generated by running the reference
// implementation (@atproto/space 0.0.0-spaces-alpha-20261112204144) with fixed keys. See
// testdata/SOURCE.
type vectors struct {
	Now    int64 `json:"now"`
	LtHash []struct {
		Ops    [][2]string `json:"ops"`
		State  string      `json:"state"`
		Digest string      `json:"digest"`
		Empty  bool        `json:"empty"`
	} `json:"lthash"`
	Commits []struct {
		Ctx     CommitCtx `json:"ctx"`
		Records []struct {
			Collection string `json:"collection"`
			Rkey       string `json:"rkey"`
			Cid        string `json:"cid"`
		} `json:"records"`
		Data            string            `json:"data"`
		SharedSecret    string            `json:"sharedSecret"`
		KeyShare        string            `json:"keyShare"`
		AcceptSignature string            `json:"acceptSignature"`
		Headers         map[string]string `json:"headers"`
	} `json:"commits"`
	RecordMacs []struct {
		URI             string            `json:"uri"`
		Cid             string            `json:"cid"`
		SharedSecret    string            `json:"sharedSecret"`
		KeyShare        string            `json:"keyShare"`
		AcceptSignature string            `json:"acceptSignature"`
		Headers         map[string]string `json:"headers"`
	} `json:"recordMacs"`
	Kem []struct {
		KemPrivateKey         string `json:"kemPrivateKey"`
		KemKey                string `json:"kemKey"`
		KeyShare              string `json:"keyShare"`
		SharedSecret          string `json:"sharedSecret"`
		AcceptCommitSignature string `json:"acceptCommitSignature"`
		AcceptRecordSignature string `json:"acceptRecordSignature"`
	} `json:"kem"`
	HTTPSig []struct {
		KeyDid  string            `json:"keyDid"`
		Headers map[string]string `json:"headers"`
	} `json:"httpsig"`
	Tokens []struct {
		Type       string          `json:"type"`
		JWT        string          `json:"jwt"`
		SigningKey string          `json:"signingKey"`
		Payload    json.RawMessage `json:"payload"`
		Header     json.RawMessage `json:"header"`
	} `json:"tokens"`
}

func loadVectors(t *testing.T) vectors {
	t.Helper()
	b, err := os.ReadFile("testdata/vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}
